package com.bank.pending;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LinkedListDemo {
    private static final Logger log = Logger.getLogger(LinkedListDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        PendingTransactions pending = new PendingTransactions();
        // Each addFront is O(1): newest pending transaction becomes the head
        pending.addFront(new BigDecimal("1000.00"));
        pending.addFront(new BigDecimal("2000.00"));
        pending.addFront(new BigDecimal("3000.00"));

        log.info("Pending transactions (head to tail):");
        pending.printAll();
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
