package com.bank.pending;

import java.math.BigDecimal;

class TransactionNode {
    BigDecimal amount;          // the data this node holds
    TransactionNode next;       // pointer to the next node (null at the end)

    TransactionNode(BigDecimal amount) {
        this.amount = amount;
        this.next = null;
    }
}
