package com.bank.pending;

import java.math.BigDecimal;
import java.util.logging.Logger;

class PendingTransactions {
    private static final Logger log = Logger.getLogger(PendingTransactions.class.getName());
    private TransactionNode head;    // reference to the first node

    // O(1) insert at front: new node points to old head, becomes new head.
    void addFront(BigDecimal amount) {
        TransactionNode node = new TransactionNode(amount);
        node.next = head;            // link new node to current chain
        head = node;                 // head now points to the new node
    }

    // Traverse: start at head, follow next until null.
    void printAll() {
        TransactionNode current = head;
        while (current != null) {
            BigDecimal amt = current.amount;
            log.info(() -> "  Rs." + amt);
            current = current.next;  // move to the next node
        }
    }
}
